$root = "D:\GITHUB  Project\Custom WorkFlow\.claude\worktrees\workspace-scan-resume-06b524"
$h = "D:\GITHUB  Project\sangam-handoff"
$b = "sangam/sangam-billing/src/main/java/org/sangam/billing"
$bt = "sangam/sangam-billing/src/test/java/org/sangam/billing"
$cp = "sangam/sangam-core/src/main/java/org/sangam/core/power"
$ct = "sangam/sangam-core/src/test/java/org/sangam/core/power"
$existing = @(
  "$b/BillingService.java", "$b/UnverifiedPayments.java", "$b/UnverifiedPayment.java", "$b/UnverifiedPaymentAuthority.java",
  "$b/UnverifiedPaymentStore.java", "$b/JdbcUnverifiedPaymentStore.java", "$b/UnverifiedPaymentPolicy.java",
  "sangam/sangam-billing/README.md", "$bt/UnverifiedPaymentsH2Test.java", "$bt/UnverifiedPaymentPolicyTest.java",
  "sangam/sangam-ledger/src/main/java/org/sangam/ledger/LedgerSchema.java",
  "sangam/sangam-rest/src/main/java/org/sangam/rest/modules/billing/UnverifiedPaymentController.java",
  "sangam/sangam-server/src/main/java/org/sangam/server/config/BillingWiring.java",
  "sangam/sangam-server/src/test/java/org/sangam/server/acceptance/contracts/UnverifiedPaymentVendorIT.java",
  "sangam/sangam-server/src/test/java/org/sangam/server/config/BillingPaymentPolicyWiringTest.java",
  "$cp/OperationMetadata.java", "$cp/PowerRuleSource.java", "$cp/PowerLimitEvaluator.java",
  "$ct/PowerLimitEvaluatorTest.java", "$ct/LegacyPowerContractsTest.java"
)
$parts = @()
foreach ($f in $existing) {
  $p = Join-Path $root ($f -replace "/", "\")
  $parts += "$f (before $((Get-FileHash $p).Hash))"
}
$parts += "NEW $b/AccrualPauses.java"
$parts += "NEW $bt/UnverifiedAccrualPauseH2Test.java"
$parts += "NEW $cp/ManifestOperationMetadata.java"
$parts += "NEW $ct/ManifestOperationMetadataTest.java"
$ts = [DateTime]::UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ")
Add-Content -Path "$h\FILE-CLAIMS.md" -Value "$ts B61 CLAIM W4-A Wave 4b round 2 (decisions 193 194 195 196 201 and the W4-M list finding): $($parts -join ' ; ')" -Encoding UTF8
$change = "$ts | W4-A/B61 | CHANGE | Round 2 behaviour and contract (W4-M please take into routes/billing.py; W4-G the schema; W4-K the manifest side of 193). (1) Decision 201: UnverifiedPaymentAuthority.Caller gains actorType STAFF, API_KEY, SERVICE or SYSTEM; UnverifiedPayments refuses every accept and resolve whose caller is not STAFF (403 NOT_PERMITTED); the REST adapter maps authMethod OIDC and SAML to STAFF, API_KEY to API_KEY, SYSTEM to SYSTEM, anything else (DEV_TOKEN, unknown, missing) to SERVICE; the old three-argument Caller stays and means SERVICE, so it is refused. Rail reconciliation keeps running as the system job. (2) Decisions 194 and 196: maker-checker is always on at resolution (resolver differs from acceptor) for every manual resolution; a channel policy maker-checker=false disables the channel (unresolved) instead of switching it off. Manual VERIFIED needs verificationRef and a new evidenceRef (400 VALIDATION_FAILED otherwise) and writes its own audit event PAYMENT_UNVERIFIED_MANUALLY_VERIFIED; REJECTED and REVERSED keep PAYMENT_UNVERIFIED_RESOLVED; rail VERIFIED keeps PAYMENT_UNVERIFIED_RESOLVED with resolvedBy system:reconciliation. The resolve request body gains evidenceRef; the resolution view gains evidenceRef. (3) Decision 195: BillingService.levyPenalties pauses accrual on the part of the arrears a pending payment covers (oldest due first, the receipt plan order) from the business date of acceptance; each suppressed amount is recorded per payment, base account and levy date in the new table BILL_UNVERIFIED_ACCRUAL_PAUSE under the payment row lock (a payment resolved meanwhile is never paused); VERIFIED forgives them (the payment counts from acceptance; the resolution audit carries the total); REJECTED and REVERSED post each suppressed amount to the penalty account (reference pen-resume:<paymentId>:<account>:<date>) and write audit event PAYMENT_UNVERIFIED_ACCRUAL_RESUMED; reconciliation completes an interrupted resumption. New column resolution_evidence_ref on BILL_UNVERIFIED_PAYMENT. (4) List: GET /billing/{ledger}/unverified-payments filters ledger, state, channel, office and minAgeDays in SQL and honours page and size (default 50, max 500) with X-Total-Count, so nothing is cut before filtering. (5) Decision 193 core side: OperationMetadata.Classification becomes (monetary, currency, limitTableKey, metadataVersion), currency required when monetary; the evaluator denies a monetary request whose currency differs from the declared one; PowerRuleSource.rules receives the classification so rules are looked up by the declared table key, never a request value; NEW ManifestOperationMetadata reads the per-pack powers declarations (W4-K supplies them from the deployed manifest generated by packgen). | W4-M W4-G W4-K W4-B integrator"
Add-Content -Path "$h\WAVE4-SYNC-BOARD.md" -Value $change -Encoding UTF8
"posted $ts"
